project.controlScriptCode:
/**
 * Dual Drone Telemetry - Control Loop
 *
 * Launches the bundled Python data generator (dual_drone_telemetry.py) automatically just before
 * the connection opens (via onConnect), so the example works without running anything by
 * hand. The helper process is stopped by Serial Studio when the device is
 * disconnected, when the project changes, or when the app quits.
 *
 * The interpreter is resolved cross-platform: "python3" is tried first
 * (Linux/macOS), falling back to "python" (typical on Windows).
 */

var helperPid = -1;

function startHelper() {
  var dir = system.projectDir();
  if (!dir.ok)
    return;

  var script = dir.result.directory + "/dual_drone_telemetry.py";

  var r = system.exec("python3", { args: ["-u", script], workingDir: dir.result.directory });
  if (!r.ok)
    r = system.exec("python", { args: ["-u", script], workingDir: dir.result.directory });

  if (r.ok)
    helperPid = r.result.processId;
}

function onConnect() {
  startHelper();
}

function setup() {}

function loop() {
  delay(1000);
}

