groups.painterCode:
// Live drone state visualizer for the Dual Drone Telemetry example.
//
// Bound datasets (in order):
//   datasets[0]  = latitude
//   datasets[1]  = longitude
//   datasets[2]  = heading        (deg, 0-360)
//   datasets[3]  = altitude       (m)
//   datasets[4]  = airspeed       (m/s)
//   datasets[5]  = vertical speed (m/s, +up)
//   datasets[6]  = roll           (deg)
//   datasets[7]  = pitch          (deg)
//   datasets[8]  = voltage        (V)
//   datasets[9]  = current        (A)
//   datasets[10] = battery        (%)
//
// Theme (Alpha = green HUD, Bravo = amber FLIR) is selected from
// group.sourceId so the same code drops into both painter groups.
//
// The widget reflows for three layout regimes:
//   FULL    -- wide and tall: side tapes + stage + bottom strip
//   SQUARE  -- close to 1:1:    big centred stage, condensed corner readouts
//   COMPACT -- small or thin:   just the dial; everything else is suppressed

const TWO_PI = Math.PI * 2;

// State
let propPhase   = 0;
let lastTs      = 0;
let chase       = 0;
let altHistory  = [];
const HIST_N    = 96;

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
function deg2rad(d) { return d * Math.PI / 180; }

function theme() {
  const isAlpha = (group.sourceId === 0) ||
                   (group.title && group.title.indexOf("Alpha") >= 0);
  if (isAlpha) {
    return {
      name:    "ALPHA",
      bg:      "#0b1410",
      panel:   "#0f1a14",
      border:  "#173823",
      grid:    "#143524",
      accent:  "#22c55e",
      accent2: "#86efac",
      muted:   "#3f6b50",
      text:    "#e2f5e8",
      dim:     "#7fa890",
      warn:    "#facc15",
      bad:     "#ef4444",
      body:    "#1e3a2a",
      bodyEdge:"#0a3a1f",
      arm:     "#1f2937",
      armEdge: "#102a18",
      cap:     "#22c55e"
    };
  }
  return {
    name:    "BRAVO",
    bg:      "#1a0f04",
    panel:   "#21160a",
    border:  "#4a2a10",
    grid:    "#3a200d",
    accent:  "#f59e0b",
    accent2: "#fbbf24",
    muted:   "#7a4a18",
    text:    "#fff7ec",
    dim:     "#c8a070",
    warn:    "#facc15",
    bad:     "#ef4444",
    body:    "#3a2410",
    bodyEdge:"#1f1208",
    arm:     "#2c1a08",
    armEdge: "#150a04",
    cap:     "#fbbf24"
  };
}

function infer_state(alt, vspeed, airspeed, battery) {
  if (alt < 1.5 && Math.abs(vspeed) < 0.5 && airspeed < 1.0) return "GROUNDED";
  if (vspeed > 5.0 && alt < 100)                              return "TAKEOFF";
  if (vspeed < -1.5 && alt < 50)                              return "LANDING";
  if (airspeed < 5.0 && alt > 30)                             return "RETURN";
  return "CRUISE";
}

function pick_layout(w, h) {
  // Pick a layout regime from the cell aspect ratio and absolute size. The
  // breakpoints were tuned for typical Serial Studio dashboard cell sizes.
  const aspect = w / h;
  if (w < 240 || h < 200)               return "compact";
  if (aspect > 1.6 && w >= 420)         return "full";
  if (aspect < 0.85 && h >= 360)        return "full";
  return "square";
}

function onFrame() {
  const now = Date.now();
  const dt  = lastTs > 0 ? Math.max(0, (now - lastTs) * 1e-3) : 0.016;
  lastTs    = now;

  if (datasets.length < 11) return;

  const airspeed = Number(datasets[4].value) || 0;
  const alt      = Number(datasets[3].value) || 0;

  const wMin   = 6.0;
  const wScale = 1.4;
  propPhase = (propPhase + (wMin + airspeed * wScale) * dt) % TWO_PI;

  chase = (chase + dt * 1.2) % 1.0;

  altHistory.push(alt);
  if (altHistory.length > HIST_N) altHistory.shift();
}

// -- generic helpers ------------------------------------------------------

function draw_panel(ctx, x, y, w, h, t, label, labelSize) {
  if (w < 6 || h < 6) return;
  ctx.fillStyle = t.panel;
  ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = t.border;
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);

  if (label && h > 18) {
    ctx.fillStyle = t.muted;
    ctx.font      = "bold " + (labelSize || 9) + "px monospace";
    ctx.textAlign = "start";
    ctx.textBaseline = "alphabetic";
    ctx.fillText(label, x + 6, y + (labelSize ? labelSize + 2 : 11));
  }
}

function draw_compass(ctx, cx, cy, r, hdg, t, opts) {
  if (r < 12) return;
  const showLabels = !opts || opts.labels !== false;
  const ticksOnly  = !!(opts && opts.ticksOnly);

  ctx.strokeStyle = t.grid;
  ctx.lineWidth   = 1;
  ctx.beginPath();
  ctx.moveTo(cx + r, cy);
  ctx.arc(cx, cy, r, 0, TWO_PI);
  ctx.stroke();

  if (!ticksOnly) {
    ctx.beginPath();
    ctx.moveTo(cx + r * 0.78, cy);
    ctx.arc(cx, cy, r * 0.78, 0, TWO_PI);
    ctx.stroke();
  }

  for (let a = 0; a < 360; a += 30) {
    const rad = deg2rad(a - 90);
    const r0  = r * 0.92;
    const r1  = (a % 90 === 0) ? r * 0.74 : r * 0.84;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(rad) * r0, cy + Math.sin(rad) * r0);
    ctx.lineTo(cx + Math.cos(rad) * r1, cy + Math.sin(rad) * r1);
    ctx.stroke();
  }

  if (showLabels && r >= 26) {
    const labelSize = r >= 60 ? 10 : 9;
    ctx.fillStyle    = t.dim;
    ctx.font         = "bold " + labelSize + "px monospace";
    ctx.textAlign    = "center";
    ctx.textBaseline = "middle";
    const lr = r * 0.62;
    ctx.fillText("N", cx,        cy - lr);
    ctx.fillText("S", cx,        cy + lr);
    ctx.fillText("E", cx + lr,   cy);
    ctx.fillText("W", cx - lr,   cy);
    ctx.textBaseline = "alphabetic";
  }

  // Heading needle.
  const hRad = deg2rad(hdg - 90);
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(hRad);

  ctx.fillStyle = t.accent;
  ctx.beginPath();
  ctx.moveTo(r * 0.72, 0);
  ctx.lineTo(0,         -4);
  ctx.lineTo(0,          4);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = t.muted;
  ctx.beginPath();
  ctx.moveTo(0, -3);
  ctx.lineTo(-r * 0.32, 0);
  ctx.lineTo(0, 3);
  ctx.closePath();
  ctx.fill();

  ctx.restore();
}

function draw_quad(ctx, cx, cy, span, t, roll) {
  if (span < 30) return;
  const armLen = span * 0.42;
  const motorR = Math.max(4, span * 0.13);
  const propR  = motorR * 1.55;

  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(deg2rad(roll));

  // Forward indicator (translucent triangle ahead of body).
  ctx.fillStyle = t.cap;
  ctx.globalAlpha = 0.4;
  ctx.beginPath();
  ctx.moveTo(0, -armLen * 0.55);
  ctx.lineTo(-6, -armLen * 0.30);
  ctx.lineTo( 6, -armLen * 0.30);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1.0;

  // Arms (X-frame).
  const armW = clamp(span * 0.04, 3, 8);
  ctx.strokeStyle = t.armEdge;
  ctx.lineWidth   = armW + 2;
  ctx.lineCap     = "round";
  ctx.beginPath();
  ctx.moveTo(-armLen, -armLen);
  ctx.lineTo( armLen,  armLen);
  ctx.moveTo( armLen, -armLen);
  ctx.lineTo(-armLen,  armLen);
  ctx.stroke();

  ctx.strokeStyle = t.arm;
  ctx.lineWidth   = armW;
  ctx.beginPath();
  ctx.moveTo(-armLen, -armLen);
  ctx.lineTo( armLen,  armLen);
  ctx.moveTo( armLen, -armLen);
  ctx.lineTo(-armLen,  armLen);
  ctx.stroke();

  ctx.lineCap = "butt";

  // Body (central capsule).
  const bodyW = span * 0.22;
  const bodyH = span * 0.16;
  ctx.fillStyle = t.body;
  ctx.fillRect(-bodyW * 0.5, -bodyH * 0.5, bodyW, bodyH);
  ctx.strokeStyle = t.bodyEdge;
  ctx.lineWidth   = 1;
  ctx.strokeRect(-bodyW * 0.5 + 0.5, -bodyH * 0.5 + 0.5, bodyW - 1, bodyH - 1);

  // Sensor lens.
  ctx.fillStyle = t.cap;
  ctx.beginPath();
  ctx.moveTo(3, -bodyH * 0.10);
  ctx.arc(0, -bodyH * 0.10, 3, 0, TWO_PI);
  ctx.fill();

  // Motors.
  const motors = [
    [-armLen, -armLen, +1],
    [ armLen, -armLen, -1],
    [-armLen,  armLen, -1],
    [ armLen,  armLen, +1]
  ];

  for (let i = 0; i < motors.length; ++i) {
    const mx = motors[i][0];
    const my = motors[i][1];
    const dir = motors[i][2];

    ctx.fillStyle = t.bodyEdge;
    ctx.beginPath();
    ctx.moveTo(mx + motorR + 1, my);
    ctx.arc(mx, my, motorR + 1, 0, TWO_PI);
    ctx.fill();

    ctx.fillStyle = t.body;
    ctx.beginPath();
    ctx.moveTo(mx + motorR, my);
    ctx.arc(mx, my, motorR, 0, TWO_PI);
    ctx.fill();

    ctx.save();
    ctx.translate(mx, my);
    ctx.rotate(propPhase * dir);

    ctx.strokeStyle = t.accent2;
    ctx.globalAlpha = 0.55;
    ctx.lineWidth   = 1.5;
    ctx.beginPath();
    ctx.moveTo(propR, 0);
    ctx.arc(0, 0, propR, 0, TWO_PI);
    ctx.stroke();
    ctx.globalAlpha = 1.0;

    ctx.strokeStyle = t.accent;
    ctx.lineWidth   = 1.5;
    ctx.lineCap     = "round";
    ctx.globalAlpha = 0.85;
    ctx.beginPath();
    ctx.moveTo(-propR, 0);
    ctx.lineTo( propR, 0);
    ctx.stroke();
    ctx.globalAlpha = 0.35;
    ctx.beginPath();
    ctx.moveTo(0, -propR);
    ctx.lineTo(0,  propR);
    ctx.stroke();
    ctx.globalAlpha = 1.0;
    ctx.lineCap     = "butt";

    ctx.fillStyle = t.cap;
    ctx.beginPath();
    ctx.moveTo(2.5, 0);
    ctx.arc(0, 0, 2.5, 0, TWO_PI);
    ctx.fill();
    ctx.restore();
  }

  ctx.restore();
}

function draw_pitch_indicator(ctx, x, y, w, h, pitch, t) {
  if (w < 26 || h < 30) return;
  draw_panel(ctx, x, y, w, h, t, null);

  const labelH   = h >= 60 ? 12 : 0;
  if (labelH > 0) {
    ctx.fillStyle    = t.muted;
    ctx.font         = "bold 8px monospace";
    ctx.textAlign    = "center";
    ctx.textBaseline = "alphabetic";
    ctx.fillText("PITCH", x + w / 2, y + 10);
  }
  const innerY = y + labelH + 2;
  const readH  = h >= 60 ? 12 : 0;
  const innerH = h - labelH - 4 - readH;
  const cx = x + w / 2;
  const cy = innerY + innerH / 2;
  const pxPerDeg = innerH / 60;
  const offset   = clamp(pitch, -45, 45) * pxPerDeg;

  ctx.save();
  ctx.beginPath();
  ctx.rect(x + 2, innerY, w - 4, innerH);
  ctx.clip();

  ctx.strokeStyle = t.accent;
  ctx.lineWidth   = 1.5;
  ctx.beginPath();
  ctx.moveTo(x + 4,     cy + offset);
  ctx.lineTo(x + w - 4, cy + offset);
  ctx.stroke();

  ctx.strokeStyle = t.grid;
  ctx.lineWidth   = 1;
  for (let p = -30; p <= 30; p += 10) {
    if (p === 0) continue;
    const ly = cy + offset - p * pxPerDeg;
    ctx.beginPath();
    ctx.moveTo(cx - 8, ly);
    ctx.lineTo(cx + 8, ly);
    ctx.stroke();
  }
  ctx.restore();

  ctx.strokeStyle = t.cap;
  ctx.lineWidth   = 2;
  ctx.beginPath();
  ctx.moveTo(cx - 8, cy);
  ctx.lineTo(cx - 3, cy);
  ctx.moveTo(cx + 3, cy);
  ctx.lineTo(cx + 8, cy);
  ctx.stroke();

  if (readH > 0) {
    ctx.fillStyle    = t.text;
    ctx.font         = "bold 10px monospace";
    ctx.textAlign    = "center";
    ctx.textBaseline = "alphabetic";
    ctx.fillText(pitch.toFixed(0) + "°", x + w / 2, y + h - 4);
  }
}

function draw_tape(ctx, x, y, w, h, value, vmin, vmax, label, units, t) {
  if (w < 24 || h < 50) return;
  draw_panel(ctx, x, y, w, h, t, label);

  const padTop = h > 80 ? 16 : 12;
  const padBot = (h > 70) ? 28 : 14;
  const top    = y + padTop;
  const bot    = y + h - padBot;
  const span   = bot - top;
  if (span < 8) return;

  ctx.strokeStyle = t.grid;
  ctx.lineWidth   = 1;
  for (let i = 0; i <= 5; ++i) {
    const ty = top + (span * i / 5);
    ctx.beginPath();
    ctx.moveTo(x + 4, ty);
    ctx.lineTo(x + w - 4, ty);
    ctx.stroke();
  }

  const norm = clamp((value - vmin) / Math.max(0.001, (vmax - vmin)), 0, 1);
  const barH = span * norm;
  ctx.fillStyle = t.accent;
  ctx.globalAlpha = 0.85;
  ctx.fillRect(x + 4, bot - barH, w - 8, barH);
  ctx.globalAlpha = 1.0;

  ctx.strokeStyle = t.accent2;
  ctx.lineWidth   = 1.5;
  ctx.beginPath();
  ctx.moveTo(x + 2,     bot - barH);
  ctx.lineTo(x + w - 2, bot - barH);
  ctx.stroke();

  ctx.fillStyle    = t.text;
  ctx.font         = "bold 11px monospace";
  ctx.textAlign    = "center";
  ctx.textBaseline = "alphabetic";
  if (h > 70) {
    ctx.fillText(value.toFixed(1), x + w / 2, y + h - 14);
    ctx.fillStyle = t.dim;
    ctx.font      = "9px monospace";
    ctx.fillText(units, x + w / 2, y + h - 4);
  } else {
    ctx.fillText(value.toFixed(0), x + w / 2, y + h - 4);
  }
}

function draw_battery(ctx, x, y, w, h, pct, voltage, current, t) {
  if (w < 80 || h < 30) return;
  draw_panel(ctx, x, y, w, h, t, "POWER");

  const tight  = h < 50 || w < 140;
  const barTop = tight ? y + 14 : y + 22;
  const barX   = x + 8;
  const barW   = w - 16;
  const barH   = tight ? 10 : 14;

  ctx.strokeStyle = t.border;
  ctx.lineWidth   = 1;
  ctx.strokeRect(barX + 0.5, barTop + 0.5, barW - 1, barH - 1);

  const fillW = (barW - 4) * clamp(pct / 100, 0, 1);
  let color   = t.accent;
  if (pct < 35) color = t.warn;
  if (pct < 15) color = t.bad;
  ctx.fillStyle = color;
  ctx.fillRect(barX + 2, barTop + 2, fillW, barH - 4);

  ctx.strokeStyle = t.grid;
  for (let i = 1; i < 4; ++i) {
    const tx = barX + (barW * i) / 4;
    ctx.beginPath();
    ctx.moveTo(tx, barTop + 2);
    ctx.lineTo(tx, barTop + barH - 2);
    ctx.stroke();
  }

  // Readouts -- two rows for narrow panels, one row otherwise.
  ctx.fillStyle    = t.text;
  ctx.font         = "bold 12px monospace";
  ctx.textAlign    = "start";
  ctx.fillText(pct.toFixed(0) + "%", x + 8, y + h - 8);

  const numericRow = voltage.toFixed(1) + "V " + current.toFixed(1) + "A";
  ctx.fillStyle = t.dim;
  ctx.font      = "10px monospace";
  ctx.textAlign = "end";
  ctx.fillText(numericRow, x + w - 8, y + h - 8);
}

function draw_alt_history(ctx, x, y, w, h, t) {
  if (w < 50 || h < 30) return;
  draw_panel(ctx, x, y, w, h, t, "ALT TRACE");
  if (altHistory.length < 2) return;

  let lo = altHistory[0], hi = altHistory[0];
  for (let i = 1; i < altHistory.length; ++i) {
    const v = altHistory[i];
    if (v < lo) lo = v;
    if (v > hi) hi = v;
  }
  if (hi - lo < 5) {
    const c = (hi + lo) * 0.5;
    lo = c - 3;
    hi = c + 3;
  }
  const padT = 16, padB = 6, padL = 4, padR = 4;
  const innerW = w - padL - padR;
  const innerH = h - padT - padB;
  if (innerW < 10 || innerH < 6) return;

  ctx.strokeStyle = t.accent;
  ctx.lineWidth   = 1.5;
  ctx.beginPath();
  for (let i = 0; i < altHistory.length; ++i) {
    const tx = x + padL + (i / (HIST_N - 1)) * innerW;
    const norm = (altHistory[i] - lo) / (hi - lo);
    const ty = y + padT + (1 - norm) * innerH;
    if (i === 0) ctx.moveTo(tx, ty);
    else         ctx.lineTo(tx, ty);
  }
  ctx.stroke();
}

function draw_state_badge(ctx, x, y, w, h, state, battery, t) {
  let color = t.muted;
  if (state === "TAKEOFF" || state === "RETURN") color = t.warn;
  if (state === "GROUNDED")                       color = t.dim;
  if (state === "CRUISE")                         color = t.accent;
  if (state === "LANDING")                        color = t.accent2;
  if (battery < 15)                               color = t.bad;

  ctx.fillStyle = color;
  ctx.fillRect(x, y, w, h);
  ctx.fillStyle    = "#0a0a0a";
  ctx.font         = "bold " + (h >= 18 ? 11 : 9) + "px monospace";
  ctx.textAlign    = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(state, x + w / 2, y + h / 2);
  ctx.textBaseline = "alphabetic";
}

function draw_link_bar(ctx, x, y, w, h, t) {
  if (w < 16 || h < 8) return;
  ctx.fillStyle = t.panel;
  ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = t.border;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);

  const dotX = x + 2 + chase * (w - 4);
  ctx.fillStyle = t.accent;
  ctx.beginPath();
  ctx.moveTo(dotX + 2, y + h * 0.5);
  ctx.arc(dotX, y + h * 0.5, 2, 0, TWO_PI);
  ctx.fill();
}

function draw_mini_battery(ctx, x, y, w, h, pct, t) {
  if (w < 30 || h < 6) return;
  ctx.strokeStyle = t.border;
  ctx.lineWidth   = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);

  const fillW = (w - 4) * clamp(pct / 100, 0, 1);
  let color   = t.accent;
  if (pct < 35) color = t.warn;
  if (pct < 15) color = t.bad;
  ctx.fillStyle = color;
  ctx.fillRect(x + 2, y + 2, fillW, h - 4);
}

// -- header ---------------------------------------------------------------

function draw_header(ctx, w, t, lat, lon, heading, state, battery, mode) {
  const compact = (mode === "compact");
  const headerH = compact ? 18 : 32;

  ctx.fillStyle    = t.text;
  ctx.font         = compact ? "bold 10px monospace" : "bold 12px monospace";
  ctx.textAlign    = "start";
  ctx.textBaseline = "alphabetic";
  ctx.fillText(compact ? t.name : "DRONE  " + t.name, 10, compact ? 13 : 16);

  if (!compact) {
    ctx.fillStyle = t.dim;
    ctx.font      = "10px monospace";
    ctx.fillText(lat.toFixed(4) + "  " + lon.toFixed(4), 10, 28);
  }

  const badgeW = compact ? 52 : Math.min(80, w * 0.30);
  const badgeH = compact ? 12 : 18;
  const badgeX = w - badgeW - 8;
  const badgeY = compact ? 4 : 6;
  draw_state_badge(ctx, badgeX, badgeY, badgeW, badgeH, state, battery, t);

  if (!compact) {
    ctx.fillStyle = t.dim;
    ctx.font      = "10px monospace";
    ctx.textAlign = "end";
    ctx.fillText("HDG  " + heading.toFixed(0).padStart(3, "0") + "°", w - 8, 36);
  }

  return headerH;
}

// -- layouts --------------------------------------------------------------

function paint_full(ctx, w, h, vals, t, headerH) {
  const top    = headerH + 4;
  const bottom = h - 6;
  const padX   = 8;

  // Side tape widths shrink slightly on tighter widgets.
  const tapeW   = clamp(w * 0.10, 44, 56);
  const stage_x = padX + tapeW + 6;
  const stage_w = Math.max(140, w - padX * 2 - tapeW * 2 - 12);

  // Reserve a bottom strip of 56 px for power/history/link.
  const bottomH = clamp(h * 0.18, 48, 64);
  const stage_h = Math.max(120, (bottom - top) - bottomH - 6);

  // Tapes.
  draw_tape(ctx, padX, top, tapeW, stage_h, vals.alt,      0, 320, "ALT", "m",   t);
  draw_tape(ctx, w - padX - tapeW, top, tapeW, stage_h, vals.airspeed, 0, 50, "AS",  "m/s", t);

  // Stage panel.
  draw_panel(ctx, stage_x, top, stage_w, stage_h, t, "ATTITUDE / HEADING");

  const cx     = stage_x + stage_w * 0.5;
  const cy     = top + stage_h * 0.5 + 4;
  const radius = Math.min(stage_w, stage_h) * 0.40;
  draw_compass(ctx, cx, cy, radius, vals.heading, t);
  draw_quad   (ctx, cx, cy, radius * 1.55, t, vals.roll);

  // Pitch column inside the stage.
  const piW = clamp(stage_w * 0.13, 44, 56);
  const piH = Math.min(stage_h * 0.55, 90);
  draw_pitch_indicator(ctx, stage_x + 6, top + 18, piW, piH, vals.pitch, t);

  // Bottom-of-stage readouts.
  ctx.fillStyle    = t.dim;
  ctx.font         = "10px monospace";
  ctx.textAlign    = "start";
  ctx.textBaseline = "alphabetic";
  ctx.fillText("ROLL  " + vals.roll.toFixed(1).padStart(6) + "°",
               stage_x + 8, top + stage_h - 22);
  ctx.fillText("AS    " + vals.airspeed.toFixed(1).padStart(6) + " m/s",
               stage_x + 8, top + stage_h - 8);

  const vsLabel = (vals.vspeed >= 0 ? "+" : "") + vals.vspeed.toFixed(1) + " m/s";
  ctx.fillStyle = (vals.vspeed > 0.5) ? t.accent : (vals.vspeed < -0.5 ? t.warn : t.dim);
  ctx.font      = "bold 11px monospace";
  ctx.textAlign = "end";
  ctx.fillText("V/S " + vsLabel, stage_x + stage_w - 8, top + stage_h - 22);
  ctx.fillStyle = t.dim;
  ctx.font      = "10px monospace";
  ctx.fillText(vals.state, stage_x + stage_w - 8, top + stage_h - 8);

  // Bottom strip.
  const bY = top + stage_h + 6;
  const bH = Math.max(40, bottom - bY);
  const linkW = clamp(w * 0.12, 60, 86);
  const slot  = Math.max(120, w - padX * 2 - linkW - 12);
  const powW  = Math.max(140, slot * 0.55);
  const histW = Math.max(40,  slot - powW - 6);
  const histX = padX + powW + 6;
  draw_battery    (ctx, padX,                bY, powW,  bH, vals.battery, vals.voltage, vals.current, t);
  draw_alt_history(ctx, histX,               bY, histW, bH, t);
  draw_link_bar   (ctx, w - padX - linkW,    bY, linkW, bH, t);
}

function paint_square(ctx, w, h, vals, t, headerH) {
  const padX   = 8;
  const top    = headerH + 4;
  const bottom = h - 6;

  // One stage that fills nearly everything; tapes collapse into a thin strip
  // along the bottom; pitch indicator sits inside the stage.
  const bottomH = clamp(h * 0.16, 40, 56);
  const stage_w = w - padX * 2;
  const stage_h = Math.max(120, bottom - top - bottomH - 6);

  draw_panel(ctx, padX, top, stage_w, stage_h, t, "ATTITUDE / HEADING");

  const cx     = padX + stage_w * 0.5;
  const cy     = top + stage_h * 0.5 + 4;
  const radius = Math.min(stage_w, stage_h) * 0.40;
  draw_compass(ctx, cx, cy, radius, vals.heading, t);
  draw_quad   (ctx, cx, cy, radius * 1.55, t, vals.roll);

  // Pitch indicator -- inside the stage, top-left.
  const piW = clamp(stage_w * 0.10, 36, 56);
  const piH = Math.min(stage_h * 0.55, 88);
  draw_pitch_indicator(ctx, padX + 6, top + 18, piW, piH, vals.pitch, t);

  // Corner readouts inside the stage. Use the four corners cleanly.
  ctx.fillStyle    = t.dim;
  ctx.font         = "10px monospace";
  ctx.textAlign    = "start";
  ctx.textBaseline = "alphabetic";
  // bottom-left: ROLL
  ctx.fillText("ROLL  " + vals.roll.toFixed(1).padStart(6) + "°",
               padX + 8, top + stage_h - 22);
  ctx.fillText("AS    " + vals.airspeed.toFixed(1).padStart(6) + " m/s",
               padX + 8, top + stage_h - 8);
  // top-right: ALT (since we dropped the tape)
  ctx.textAlign = "end";
  ctx.fillStyle = t.text;
  ctx.font      = "bold 12px monospace";
  ctx.fillText(vals.alt.toFixed(0) + " m", padX + stage_w - 8, top + 22);
  // bottom-right: V/S + state
  const vsLabel = (vals.vspeed >= 0 ? "+" : "") + vals.vspeed.toFixed(1) + " m/s";
  ctx.fillStyle = (vals.vspeed > 0.5) ? t.accent : (vals.vspeed < -0.5 ? t.warn : t.dim);
  ctx.font      = "bold 11px monospace";
  ctx.fillText("V/S " + vsLabel, padX + stage_w - 8, top + stage_h - 22);
  ctx.fillStyle = t.dim;
  ctx.font      = "10px monospace";
  ctx.fillText(vals.state, padX + stage_w - 8, top + stage_h - 8);

  // Bottom strip: condensed power + link.
  const bY = top + stage_h + 6;
  const bH = Math.max(36, bottom - bY);
  const linkW = clamp(w * 0.16, 50, 80);
  const powW  = Math.max(140, w - padX * 2 - linkW - 6);
  draw_battery (ctx, padX,             bY, powW,  bH, vals.battery, vals.voltage, vals.current, t);
  draw_link_bar(ctx, w - padX - linkW, bY, linkW, bH, t);
}

function paint_compact(ctx, w, h, vals, t, headerH) {
  // Tiny variant: drop the panel chrome, just show the dial centred plus
  // a stack of small numeric readouts on the right edge.
  const padX = 6;
  const top  = headerH + 2;

  const colW = Math.min(76, w * 0.32);
  const stage_w = w - padX * 2 - colW - 4;
  const stage_h = h - top - 6;

  // Centre the dial in the available stage area.
  const cx = padX + stage_w * 0.5;
  const cy = top + stage_h * 0.5;
  const radius = Math.max(20, Math.min(stage_w, stage_h) * 0.46);
  draw_compass(ctx, cx, cy, radius, vals.heading, t, { ticksOnly: true, labels: radius >= 32 });
  draw_quad   (ctx, cx, cy, radius * 1.55, t, vals.roll);

  // Right-side numeric column.
  const rx = padX + stage_w + 6;
  const ry = top;
  const rw = colW - 2;
  const rh = h - top - 6;
  const lineH = Math.max(13, Math.min(18, rh / 6));

  ctx.textAlign    = "start";
  ctx.textBaseline = "alphabetic";

  // Battery mini-bar across the top of the column.
  const bbH = 8;
  draw_mini_battery(ctx, rx, ry, rw, bbH, vals.battery, t);
  ctx.fillStyle = t.dim;
  ctx.font      = "9px monospace";
  ctx.fillText(vals.battery.toFixed(0) + "%  "
               + vals.voltage.toFixed(1) + "V", rx, ry + bbH + 10);

  // Stack the rest.
  const startY = ry + bbH + 22;
  const rows = [
    { label: "ALT",  value: vals.alt.toFixed(0)      + " m",   color: t.text },
    { label: "AS",   value: vals.airspeed.toFixed(1) + " m/s", color: t.text },
    { label: "V/S",  value: (vals.vspeed >= 0 ? "+" : "")
                              + vals.vspeed.toFixed(1) + " m/s",
                     color: vals.vspeed > 0.5 ? t.accent : vals.vspeed < -0.5 ? t.warn : t.dim },
    { label: "HDG",  value: vals.heading.toFixed(0).padStart(3, "0") + "°", color: t.text },
    { label: "ROLL", value: vals.roll.toFixed(0)  + "°", color: t.dim },
    { label: "PTCH", value: vals.pitch.toFixed(0) + "°", color: t.dim }
  ];

  for (let i = 0; i < rows.length; ++i) {
    const ly = startY + i * lineH;
    if (ly + lineH > h - 4) break;
    ctx.fillStyle = t.muted;
    ctx.font      = "9px monospace";
    ctx.textAlign = "start";
    ctx.fillText(rows[i].label, rx, ly);
    ctx.fillStyle = rows[i].color;
    ctx.font      = "bold 10px monospace";
    ctx.textAlign = "end";
    ctx.fillText(rows[i].value, rx + rw, ly);
  }
}

// -- entry point ----------------------------------------------------------

function paint(ctx, w, h) {
  const t = theme();

  ctx.fillStyle = t.bg;
  ctx.fillRect(0, 0, w, h);

  if (datasets.length < 11) {
    ctx.fillStyle    = t.dim;
    ctx.font         = (w < 320 ? "9px" : "11px") + " monospace";
    ctx.textAlign    = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("Waiting for telemetry...", w / 2, h / 2);
    return;
  }

  const vals = {
    lat:      Number(datasets[0].value)  || 0,
    lon:      Number(datasets[1].value)  || 0,
    heading:  Number(datasets[2].value)  || 0,
    alt:      Number(datasets[3].value)  || 0,
    airspeed: Number(datasets[4].value)  || 0,
    vspeed:   Number(datasets[5].value)  || 0,
    roll:     Number(datasets[6].value)  || 0,
    pitch:    Number(datasets[7].value)  || 0,
    voltage:  Number(datasets[8].value)  || 0,
    current:  Number(datasets[9].value)  || 0,
    battery:  Number(datasets[10].value) || 0
  };
  vals.state = infer_state(vals.alt, vals.vspeed, vals.airspeed, vals.battery);

  const mode    = pick_layout(w, h);
  const headerH = draw_header(ctx, w, t, vals.lat, vals.lon, vals.heading,
                              vals.state, vals.battery, mode);

  if      (mode === "full")    paint_full   (ctx, w, h, vals, t, headerH);
  else if (mode === "square")  paint_square (ctx, w, h, vals, t, headerH);
  else                          paint_compact(ctx, w, h, vals, t, headerH);
}

// Live drone state visualizer for the Dual Drone Telemetry example.
//
// Bound datasets (in order):
//   datasets[0]  = latitude
//   datasets[1]  = longitude
//   datasets[2]  = heading        (deg, 0-360)
//   datasets[3]  = altitude       (m)
//   datasets[4]  = airspeed       (m/s)
//   datasets[5]  = vertical speed (m/s, +up)
//   datasets[6]  = roll           (deg)
//   datasets[7]  = pitch          (deg)
//   datasets[8]  = voltage        (V)
//   datasets[9]  = current        (A)
//   datasets[10] = battery        (%)
//
// Theme (Alpha = green HUD, Bravo = amber FLIR) is selected from
// group.sourceId so the same code drops into both painter groups.
//
// The widget reflows for three layout regimes:
//   FULL    -- wide and tall: side tapes + stage + bottom strip
//   SQUARE  -- close to 1:1:    big centred stage, condensed corner readouts
//   COMPACT -- small or thin:   just the dial; everything else is suppressed

const TWO_PI = Math.PI * 2;

// State
let propPhase   = 0;
let lastTs      = 0;
let chase       = 0;
let altHistory  = [];
const HIST_N    = 96;

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
function deg2rad(d) { return d * Math.PI / 180; }

function theme() {
  const isAlpha = (group.sourceId === 0) ||
                   (group.title && group.title.indexOf("Alpha") >= 0);
  if (isAlpha) {
    return {
      name:    "ALPHA",
      bg:      "#0b1410",
      panel:   "#0f1a14",
      border:  "#173823",
      grid:    "#143524",
      accent:  "#22c55e",
      accent2: "#86efac",
      muted:   "#3f6b50",
      text:    "#e2f5e8",
      dim:     "#7fa890",
      warn:    "#facc15",
      bad:     "#ef4444",
      body:    "#1e3a2a",
      bodyEdge:"#0a3a1f",
      arm:     "#1f2937",
      armEdge: "#102a18",
      cap:     "#22c55e"
    };
  }
  return {
    name:    "BRAVO",
    bg:      "#1a0f04",
    panel:   "#21160a",
    border:  "#4a2a10",
    grid:    "#3a200d",
    accent:  "#f59e0b",
    accent2: "#fbbf24",
    muted:   "#7a4a18",
    text:    "#fff7ec",
    dim:     "#c8a070",
    warn:    "#facc15",
    bad:     "#ef4444",
    body:    "#3a2410",
    bodyEdge:"#1f1208",
    arm:     "#2c1a08",
    armEdge: "#150a04",
    cap:     "#fbbf24"
  };
}

function infer_state(alt, vspeed, airspeed, battery) {
  if (alt < 1.5 && Math.abs(vspeed) < 0.5 && airspeed < 1.0) return "GROUNDED";
  if (vspeed > 5.0 && alt < 100)                              return "TAKEOFF";
  if (vspeed < -1.5 && alt < 50)                              return "LANDING";
  if (airspeed < 5.0 && alt > 30)                             return "RETURN";
  return "CRUISE";
}

function pick_layout(w, h) {
  // Pick a layout regime from the cell aspect ratio and absolute size. The
  // breakpoints were tuned for typical Serial Studio dashboard cell sizes.
  const aspect = w / h;
  if (w < 240 || h < 200)               return "compact";
  if (aspect > 1.6 && w >= 420)         return "full";
  if (aspect < 0.85 && h >= 360)        return "full";
  return "square";
}

function onFrame() {
  const now = Date.now();
  const dt  = lastTs > 0 ? Math.max(0, (now - lastTs) * 1e-3) : 0.016;
  lastTs    = now;

  if (datasets.length < 11) return;

  const airspeed = Number(datasets[4].value) || 0;
  const alt      = Number(datasets[3].value) || 0;

  const wMin   = 6.0;
  const wScale = 1.4;
  propPhase = (propPhase + (wMin + airspeed * wScale) * dt) % TWO_PI;

  chase = (chase + dt * 1.2) % 1.0;

  altHistory.push(alt);
  if (altHistory.length > HIST_N) altHistory.shift();
}

// -- generic helpers ------------------------------------------------------

function draw_panel(ctx, x, y, w, h, t, label, labelSize) {
  if (w < 6 || h < 6) return;
  ctx.fillStyle = t.panel;
  ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = t.border;
  ctx.lineWidth = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);

  if (label && h > 18) {
    ctx.fillStyle = t.muted;
    ctx.font      = "bold " + (labelSize || 9) + "px monospace";
    ctx.textAlign = "start";
    ctx.textBaseline = "alphabetic";
    ctx.fillText(label, x + 6, y + (labelSize ? labelSize + 2 : 11));
  }
}

function draw_compass(ctx, cx, cy, r, hdg, t, opts) {
  if (r < 12) return;
  const showLabels = !opts || opts.labels !== false;
  const ticksOnly  = !!(opts && opts.ticksOnly);

  ctx.strokeStyle = t.grid;
  ctx.lineWidth   = 1;
  ctx.beginPath();
  ctx.moveTo(cx + r, cy);
  ctx.arc(cx, cy, r, 0, TWO_PI);
  ctx.stroke();

  if (!ticksOnly) {
    ctx.beginPath();
    ctx.moveTo(cx + r * 0.78, cy);
    ctx.arc(cx, cy, r * 0.78, 0, TWO_PI);
    ctx.stroke();
  }

  for (let a = 0; a < 360; a += 30) {
    const rad = deg2rad(a - 90);
    const r0  = r * 0.92;
    const r1  = (a % 90 === 0) ? r * 0.74 : r * 0.84;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(rad) * r0, cy + Math.sin(rad) * r0);
    ctx.lineTo(cx + Math.cos(rad) * r1, cy + Math.sin(rad) * r1);
    ctx.stroke();
  }

  if (showLabels && r >= 26) {
    const labelSize = r >= 60 ? 10 : 9;
    ctx.fillStyle    = t.dim;
    ctx.font         = "bold " + labelSize + "px monospace";
    ctx.textAlign    = "center";
    ctx.textBaseline = "middle";
    const lr = r * 0.62;
    ctx.fillText("N", cx,        cy - lr);
    ctx.fillText("S", cx,        cy + lr);
    ctx.fillText("E", cx + lr,   cy);
    ctx.fillText("W", cx - lr,   cy);
    ctx.textBaseline = "alphabetic";
  }

  // Heading needle.
  const hRad = deg2rad(hdg - 90);
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(hRad);

  ctx.fillStyle = t.accent;
  ctx.beginPath();
  ctx.moveTo(r * 0.72, 0);
  ctx.lineTo(0,         -4);
  ctx.lineTo(0,          4);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = t.muted;
  ctx.beginPath();
  ctx.moveTo(0, -3);
  ctx.lineTo(-r * 0.32, 0);
  ctx.lineTo(0, 3);
  ctx.closePath();
  ctx.fill();

  ctx.restore();
}

function draw_quad(ctx, cx, cy, span, t, roll) {
  if (span < 30) return;
  const armLen = span * 0.42;
  const motorR = Math.max(4, span * 0.13);
  const propR  = motorR * 1.55;

  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(deg2rad(roll));

  // Forward indicator (translucent triangle ahead of body).
  ctx.fillStyle = t.cap;
  ctx.globalAlpha = 0.4;
  ctx.beginPath();
  ctx.moveTo(0, -armLen * 0.55);
  ctx.lineTo(-6, -armLen * 0.30);
  ctx.lineTo( 6, -armLen * 0.30);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1.0;

  // Arms (X-frame).
  const armW = clamp(span * 0.04, 3, 8);
  ctx.strokeStyle = t.armEdge;
  ctx.lineWidth   = armW + 2;
  ctx.lineCap     = "round";
  ctx.beginPath();
  ctx.moveTo(-armLen, -armLen);
  ctx.lineTo( armLen,  armLen);
  ctx.moveTo( armLen, -armLen);
  ctx.lineTo(-armLen,  armLen);
  ctx.stroke();

  ctx.strokeStyle = t.arm;
  ctx.lineWidth   = armW;
  ctx.beginPath();
  ctx.moveTo(-armLen, -armLen);
  ctx.lineTo( armLen,  armLen);
  ctx.moveTo( armLen, -armLen);
  ctx.lineTo(-armLen,  armLen);
  ctx.stroke();

  ctx.lineCap = "butt";

  // Body (central capsule).
  const bodyW = span * 0.22;
  const bodyH = span * 0.16;
  ctx.fillStyle = t.body;
  ctx.fillRect(-bodyW * 0.5, -bodyH * 0.5, bodyW, bodyH);
  ctx.strokeStyle = t.bodyEdge;
  ctx.lineWidth   = 1;
  ctx.strokeRect(-bodyW * 0.5 + 0.5, -bodyH * 0.5 + 0.5, bodyW - 1, bodyH - 1);

  // Sensor lens.
  ctx.fillStyle = t.cap;
  ctx.beginPath();
  ctx.moveTo(3, -bodyH * 0.10);
  ctx.arc(0, -bodyH * 0.10, 3, 0, TWO_PI);
  ctx.fill();

  // Motors.
  const motors = [
    [-armLen, -armLen, +1],
    [ armLen, -armLen, -1],
    [-armLen,  armLen, -1],
    [ armLen,  armLen, +1]
  ];

  for (let i = 0; i < motors.length; ++i) {
    const mx = motors[i][0];
    const my = motors[i][1];
    const dir = motors[i][2];

    ctx.fillStyle = t.bodyEdge;
    ctx.beginPath();
    ctx.moveTo(mx + motorR + 1, my);
    ctx.arc(mx, my, motorR + 1, 0, TWO_PI);
    ctx.fill();

    ctx.fillStyle = t.body;
    ctx.beginPath();
    ctx.moveTo(mx + motorR, my);
    ctx.arc(mx, my, motorR, 0, TWO_PI);
    ctx.fill();

    ctx.save();
    ctx.translate(mx, my);
    ctx.rotate(propPhase * dir);

    ctx.strokeStyle = t.accent2;
    ctx.globalAlpha = 0.55;
    ctx.lineWidth   = 1.5;
    ctx.beginPath();
    ctx.moveTo(propR, 0);
    ctx.arc(0, 0, propR, 0, TWO_PI);
    ctx.stroke();
    ctx.globalAlpha = 1.0;

    ctx.strokeStyle = t.accent;
    ctx.lineWidth   = 1.5;
    ctx.lineCap     = "round";
    ctx.globalAlpha = 0.85;
    ctx.beginPath();
    ctx.moveTo(-propR, 0);
    ctx.lineTo( propR, 0);
    ctx.stroke();
    ctx.globalAlpha = 0.35;
    ctx.beginPath();
    ctx.moveTo(0, -propR);
    ctx.lineTo(0,  propR);
    ctx.stroke();
    ctx.globalAlpha = 1.0;
    ctx.lineCap     = "butt";

    ctx.fillStyle = t.cap;
    ctx.beginPath();
    ctx.moveTo(2.5, 0);
    ctx.arc(0, 0, 2.5, 0, TWO_PI);
    ctx.fill();
    ctx.restore();
  }

  ctx.restore();
}

function draw_pitch_indicator(ctx, x, y, w, h, pitch, t) {
  if (w < 26 || h < 30) return;
  draw_panel(ctx, x, y, w, h, t, null);

  const labelH   = h >= 60 ? 12 : 0;
  if (labelH > 0) {
    ctx.fillStyle    = t.muted;
    ctx.font         = "bold 8px monospace";
    ctx.textAlign    = "center";
    ctx.textBaseline = "alphabetic";
    ctx.fillText("PITCH", x + w / 2, y + 10);
  }
  const innerY = y + labelH + 2;
  const readH  = h >= 60 ? 12 : 0;
  const innerH = h - labelH - 4 - readH;
  const cx = x + w / 2;
  const cy = innerY + innerH / 2;
  const pxPerDeg = innerH / 60;
  const offset   = clamp(pitch, -45, 45) * pxPerDeg;

  ctx.save();
  ctx.beginPath();
  ctx.rect(x + 2, innerY, w - 4, innerH);
  ctx.clip();

  ctx.strokeStyle = t.accent;
  ctx.lineWidth   = 1.5;
  ctx.beginPath();
  ctx.moveTo(x + 4,     cy + offset);
  ctx.lineTo(x + w - 4, cy + offset);
  ctx.stroke();

  ctx.strokeStyle = t.grid;
  ctx.lineWidth   = 1;
  for (let p = -30; p <= 30; p += 10) {
    if (p === 0) continue;
    const ly = cy + offset - p * pxPerDeg;
    ctx.beginPath();
    ctx.moveTo(cx - 8, ly);
    ctx.lineTo(cx + 8, ly);
    ctx.stroke();
  }
  ctx.restore();

  ctx.strokeStyle = t.cap;
  ctx.lineWidth   = 2;
  ctx.beginPath();
  ctx.moveTo(cx - 8, cy);
  ctx.lineTo(cx - 3, cy);
  ctx.moveTo(cx + 3, cy);
  ctx.lineTo(cx + 8, cy);
  ctx.stroke();

  if (readH > 0) {
    ctx.fillStyle    = t.text;
    ctx.font         = "bold 10px monospace";
    ctx.textAlign    = "center";
    ctx.textBaseline = "alphabetic";
    ctx.fillText(pitch.toFixed(0) + "°", x + w / 2, y + h - 4);
  }
}

function draw_tape(ctx, x, y, w, h, value, vmin, vmax, label, units, t) {
  if (w < 24 || h < 50) return;
  draw_panel(ctx, x, y, w, h, t, label);

  const padTop = h > 80 ? 16 : 12;
  const padBot = (h > 70) ? 28 : 14;
  const top    = y + padTop;
  const bot    = y + h - padBot;
  const span   = bot - top;
  if (span < 8) return;

  ctx.strokeStyle = t.grid;
  ctx.lineWidth   = 1;
  for (let i = 0; i <= 5; ++i) {
    const ty = top + (span * i / 5);
    ctx.beginPath();
    ctx.moveTo(x + 4, ty);
    ctx.lineTo(x + w - 4, ty);
    ctx.stroke();
  }

  const norm = clamp((value - vmin) / Math.max(0.001, (vmax - vmin)), 0, 1);
  const barH = span * norm;
  ctx.fillStyle = t.accent;
  ctx.globalAlpha = 0.85;
  ctx.fillRect(x + 4, bot - barH, w - 8, barH);
  ctx.globalAlpha = 1.0;

  ctx.strokeStyle = t.accent2;
  ctx.lineWidth   = 1.5;
  ctx.beginPath();
  ctx.moveTo(x + 2,     bot - barH);
  ctx.lineTo(x + w - 2, bot - barH);
  ctx.stroke();

  ctx.fillStyle    = t.text;
  ctx.font         = "bold 11px monospace";
  ctx.textAlign    = "center";
  ctx.textBaseline = "alphabetic";
  if (h > 70) {
    ctx.fillText(value.toFixed(1), x + w / 2, y + h - 14);
    ctx.fillStyle = t.dim;
    ctx.font      = "9px monospace";
    ctx.fillText(units, x + w / 2, y + h - 4);
  } else {
    ctx.fillText(value.toFixed(0), x + w / 2, y + h - 4);
  }
}

function draw_battery(ctx, x, y, w, h, pct, voltage, current, t) {
  if (w < 80 || h < 30) return;
  draw_panel(ctx, x, y, w, h, t, "POWER");

  const tight  = h < 50 || w < 140;
  const barTop = tight ? y + 14 : y + 22;
  const barX   = x + 8;
  const barW   = w - 16;
  const barH   = tight ? 10 : 14;

  ctx.strokeStyle = t.border;
  ctx.lineWidth   = 1;
  ctx.strokeRect(barX + 0.5, barTop + 0.5, barW - 1, barH - 1);

  const fillW = (barW - 4) * clamp(pct / 100, 0, 1);
  let color   = t.accent;
  if (pct < 35) color = t.warn;
  if (pct < 15) color = t.bad;
  ctx.fillStyle = color;
  ctx.fillRect(barX + 2, barTop + 2, fillW, barH - 4);

  ctx.strokeStyle = t.grid;
  for (let i = 1; i < 4; ++i) {
    const tx = barX + (barW * i) / 4;
    ctx.beginPath();
    ctx.moveTo(tx, barTop + 2);
    ctx.lineTo(tx, barTop + barH - 2);
    ctx.stroke();
  }

  // Readouts -- two rows for narrow panels, one row otherwise.
  ctx.fillStyle    = t.text;
  ctx.font         = "bold 12px monospace";
  ctx.textAlign    = "start";
  ctx.fillText(pct.toFixed(0) + "%", x + 8, y + h - 8);

  const numericRow = voltage.toFixed(1) + "V " + current.toFixed(1) + "A";
  ctx.fillStyle = t.dim;
  ctx.font      = "10px monospace";
  ctx.textAlign = "end";
  ctx.fillText(numericRow, x + w - 8, y + h - 8);
}

function draw_alt_history(ctx, x, y, w, h, t) {
  if (w < 50 || h < 30) return;
  draw_panel(ctx, x, y, w, h, t, "ALT TRACE");
  if (altHistory.length < 2) return;

  let lo = altHistory[0], hi = altHistory[0];
  for (let i = 1; i < altHistory.length; ++i) {
    const v = altHistory[i];
    if (v < lo) lo = v;
    if (v > hi) hi = v;
  }
  if (hi - lo < 5) {
    const c = (hi + lo) * 0.5;
    lo = c - 3;
    hi = c + 3;
  }
  const padT = 16, padB = 6, padL = 4, padR = 4;
  const innerW = w - padL - padR;
  const innerH = h - padT - padB;
  if (innerW < 10 || innerH < 6) return;

  ctx.strokeStyle = t.accent;
  ctx.lineWidth   = 1.5;
  ctx.beginPath();
  for (let i = 0; i < altHistory.length; ++i) {
    const tx = x + padL + (i / (HIST_N - 1)) * innerW;
    const norm = (altHistory[i] - lo) / (hi - lo);
    const ty = y + padT + (1 - norm) * innerH;
    if (i === 0) ctx.moveTo(tx, ty);
    else         ctx.lineTo(tx, ty);
  }
  ctx.stroke();
}

function draw_state_badge(ctx, x, y, w, h, state, battery, t) {
  let color = t.muted;
  if (state === "TAKEOFF" || state === "RETURN") color = t.warn;
  if (state === "GROUNDED")                       color = t.dim;
  if (state === "CRUISE")                         color = t.accent;
  if (state === "LANDING")                        color = t.accent2;
  if (battery < 15)                               color = t.bad;

  ctx.fillStyle = color;
  ctx.fillRect(x, y, w, h);
  ctx.fillStyle    = "#0a0a0a";
  ctx.font         = "bold " + (h >= 18 ? 11 : 9) + "px monospace";
  ctx.textAlign    = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(state, x + w / 2, y + h / 2);
  ctx.textBaseline = "alphabetic";
}

function draw_link_bar(ctx, x, y, w, h, t) {
  if (w < 16 || h < 8) return;
  ctx.fillStyle = t.panel;
  ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = t.border;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);

  const dotX = x + 2 + chase * (w - 4);
  ctx.fillStyle = t.accent;
  ctx.beginPath();
  ctx.moveTo(dotX + 2, y + h * 0.5);
  ctx.arc(dotX, y + h * 0.5, 2, 0, TWO_PI);
  ctx.fill();
}

function draw_mini_battery(ctx, x, y, w, h, pct, t) {
  if (w < 30 || h < 6) return;
  ctx.strokeStyle = t.border;
  ctx.lineWidth   = 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);

  const fillW = (w - 4) * clamp(pct / 100, 0, 1);
  let color   = t.accent;
  if (pct < 35) color = t.warn;
  if (pct < 15) color = t.bad;
  ctx.fillStyle = color;
  ctx.fillRect(x + 2, y + 2, fillW, h - 4);
}

// -- header ---------------------------------------------------------------

function draw_header(ctx, w, t, lat, lon, heading, state, battery, mode) {
  const compact = (mode === "compact");
  const headerH = compact ? 18 : 32;

  ctx.fillStyle    = t.text;
  ctx.font         = compact ? "bold 10px monospace" : "bold 12px monospace";
  ctx.textAlign    = "start";
  ctx.textBaseline = "alphabetic";
  ctx.fillText(compact ? t.name : "DRONE  " + t.name, 10, compact ? 13 : 16);

  if (!compact) {
    ctx.fillStyle = t.dim;
    ctx.font      = "10px monospace";
    ctx.fillText(lat.toFixed(4) + "  " + lon.toFixed(4), 10, 28);
  }

  const badgeW = compact ? 52 : Math.min(80, w * 0.30);
  const badgeH = compact ? 12 : 18;
  const badgeX = w - badgeW - 8;
  const badgeY = compact ? 4 : 6;
  draw_state_badge(ctx, badgeX, badgeY, badgeW, badgeH, state, battery, t);

  if (!compact) {
    ctx.fillStyle = t.dim;
    ctx.font      = "10px monospace";
    ctx.textAlign = "end";
    ctx.fillText("HDG  " + heading.toFixed(0).padStart(3, "0") + "°", w - 8, 36);
  }

  return headerH;
}

// -- layouts --------------------------------------------------------------

function paint_full(ctx, w, h, vals, t, headerH) {
  const top    = headerH + 4;
  const bottom = h - 6;
  const padX   = 8;

  // Side tape widths shrink slightly on tighter widgets.
  const tapeW   = clamp(w * 0.10, 44, 56);
  const stage_x = padX + tapeW + 6;
  const stage_w = Math.max(140, w - padX * 2 - tapeW * 2 - 12);

  // Reserve a bottom strip of 56 px for power/history/link.
  const bottomH = clamp(h * 0.18, 48, 64);
  const stage_h = Math.max(120, (bottom - top) - bottomH - 6);

  // Tapes.
  draw_tape(ctx, padX, top, tapeW, stage_h, vals.alt,      0, 320, "ALT", "m",   t);
  draw_tape(ctx, w - padX - tapeW, top, tapeW, stage_h, vals.airspeed, 0, 50, "AS",  "m/s", t);

  // Stage panel.
  draw_panel(ctx, stage_x, top, stage_w, stage_h, t, "ATTITUDE / HEADING");

  const cx     = stage_x + stage_w * 0.5;
  const cy     = top + stage_h * 0.5 + 4;
  const radius = Math.min(stage_w, stage_h) * 0.40;
  draw_compass(ctx, cx, cy, radius, vals.heading, t);
  draw_quad   (ctx, cx, cy, radius * 1.55, t, vals.roll);

  // Pitch column inside the stage.
  const piW = clamp(stage_w * 0.13, 44, 56);
  const piH = Math.min(stage_h * 0.55, 90);
  draw_pitch_indicator(ctx, stage_x + 6, top + 18, piW, piH, vals.pitch, t);

  // Bottom-of-stage readouts.
  ctx.fillStyle    = t.dim;
  ctx.font         = "10px monospace";
  ctx.textAlign    = "start";
  ctx.textBaseline = "alphabetic";
  ctx.fillText("ROLL  " + vals.roll.toFixed(1).padStart(6) + "°",
               stage_x + 8, top + stage_h - 22);
  ctx.fillText("AS    " + vals.airspeed.toFixed(1).padStart(6) + " m/s",
               stage_x + 8, top + stage_h - 8);

  const vsLabel = (vals.vspeed >= 0 ? "+" : "") + vals.vspeed.toFixed(1) + " m/s";
  ctx.fillStyle = (vals.vspeed > 0.5) ? t.accent : (vals.vspeed < -0.5 ? t.warn : t.dim);
  ctx.font      = "bold 11px monospace";
  ctx.textAlign = "end";
  ctx.fillText("V/S " + vsLabel, stage_x + stage_w - 8, top + stage_h - 22);
  ctx.fillStyle = t.dim;
  ctx.font      = "10px monospace";
  ctx.fillText(vals.state, stage_x + stage_w - 8, top + stage_h - 8);

  // Bottom strip.
  const bY = top + stage_h + 6;
  const bH = Math.max(40, bottom - bY);
  const linkW = clamp(w * 0.12, 60, 86);
  const slot  = Math.max(120, w - padX * 2 - linkW - 12);
  const powW  = Math.max(140, slot * 0.55);
  const histW = Math.max(40,  slot - powW - 6);
  const histX = padX + powW + 6;
  draw_battery    (ctx, padX,                bY, powW,  bH, vals.battery, vals.voltage, vals.current, t);
  draw_alt_history(ctx, histX,               bY, histW, bH, t);
  draw_link_bar   (ctx, w - padX - linkW,    bY, linkW, bH, t);
}

function paint_square(ctx, w, h, vals, t, headerH) {
  const padX   = 8;
  const top    = headerH + 4;
  const bottom = h - 6;

  // One stage that fills nearly everything; tapes collapse into a thin strip
  // along the bottom; pitch indicator sits inside the stage.
  const bottomH = clamp(h * 0.16, 40, 56);
  const stage_w = w - padX * 2;
  const stage_h = Math.max(120, bottom - top - bottomH - 6);

  draw_panel(ctx, padX, top, stage_w, stage_h, t, "ATTITUDE / HEADING");

  const cx     = padX + stage_w * 0.5;
  const cy     = top + stage_h * 0.5 + 4;
  const radius = Math.min(stage_w, stage_h) * 0.40;
  draw_compass(ctx, cx, cy, radius, vals.heading, t);
  draw_quad   (ctx, cx, cy, radius * 1.55, t, vals.roll);

  // Pitch indicator -- inside the stage, top-left.
  const piW = clamp(stage_w * 0.10, 36, 56);
  const piH = Math.min(stage_h * 0.55, 88);
  draw_pitch_indicator(ctx, padX + 6, top + 18, piW, piH, vals.pitch, t);

  // Corner readouts inside the stage. Use the four corners cleanly.
  ctx.fillStyle    = t.dim;
  ctx.font         = "10px monospace";
  ctx.textAlign    = "start";
  ctx.textBaseline = "alphabetic";
  // bottom-left: ROLL
  ctx.fillText("ROLL  " + vals.roll.toFixed(1).padStart(6) + "°",
               padX + 8, top + stage_h - 22);
  ctx.fillText("AS    " + vals.airspeed.toFixed(1).padStart(6) + " m/s",
               padX + 8, top + stage_h - 8);
  // top-right: ALT (since we dropped the tape)
  ctx.textAlign = "end";
  ctx.fillStyle = t.text;
  ctx.font      = "bold 12px monospace";
  ctx.fillText(vals.alt.toFixed(0) + " m", padX + stage_w - 8, top + 22);
  // bottom-right: V/S + state
  const vsLabel = (vals.vspeed >= 0 ? "+" : "") + vals.vspeed.toFixed(1) + " m/s";
  ctx.fillStyle = (vals.vspeed > 0.5) ? t.accent : (vals.vspeed < -0.5 ? t.warn : t.dim);
  ctx.font      = "bold 11px monospace";
  ctx.fillText("V/S " + vsLabel, padX + stage_w - 8, top + stage_h - 22);
  ctx.fillStyle = t.dim;
  ctx.font      = "10px monospace";
  ctx.fillText(vals.state, padX + stage_w - 8, top + stage_h - 8);

  // Bottom strip: condensed power + link.
  const bY = top + stage_h + 6;
  const bH = Math.max(36, bottom - bY);
  const linkW = clamp(w * 0.16, 50, 80);
  const powW  = Math.max(140, w - padX * 2 - linkW - 6);
  draw_battery (ctx, padX,             bY, powW,  bH, vals.battery, vals.voltage, vals.current, t);
  draw_link_bar(ctx, w - padX - linkW, bY, linkW, bH, t);
}

function paint_compact(ctx, w, h, vals, t, headerH) {
  // Tiny variant: drop the panel chrome, just show the dial centred plus
  // a stack of small numeric readouts on the right edge.
  const padX = 6;
  const top  = headerH + 2;

  const colW = Math.min(76, w * 0.32);
  const stage_w = w - padX * 2 - colW - 4;
  const stage_h = h - top - 6;

  // Centre the dial in the available stage area.
  const cx = padX + stage_w * 0.5;
  const cy = top + stage_h * 0.5;
  const radius = Math.max(20, Math.min(stage_w, stage_h) * 0.46);
  draw_compass(ctx, cx, cy, radius, vals.heading, t, { ticksOnly: true, labels: radius >= 32 });
  draw_quad   (ctx, cx, cy, radius * 1.55, t, vals.roll);

  // Right-side numeric column.
  const rx = padX + stage_w + 6;
  const ry = top;
  const rw = colW - 2;
  const rh = h - top - 6;
  const lineH = Math.max(13, Math.min(18, rh / 6));

  ctx.textAlign    = "start";
  ctx.textBaseline = "alphabetic";

  // Battery mini-bar across the top of the column.
  const bbH = 8;
  draw_mini_battery(ctx, rx, ry, rw, bbH, vals.battery, t);
  ctx.fillStyle = t.dim;
  ctx.font      = "9px monospace";
  ctx.fillText(vals.battery.toFixed(0) + "%  "
               + vals.voltage.toFixed(1) + "V", rx, ry + bbH + 10);

  // Stack the rest.
  const startY = ry + bbH + 22;
  const rows = [
    { label: "ALT",  value: vals.alt.toFixed(0)      + " m",   color: t.text },
    { label: "AS",   value: vals.airspeed.toFixed(1) + " m/s", color: t.text },
    { label: "V/S",  value: (vals.vspeed >= 0 ? "+" : "")
                              + vals.vspeed.toFixed(1) + " m/s",
                     color: vals.vspeed > 0.5 ? t.accent : vals.vspeed < -0.5 ? t.warn : t.dim },
    { label: "HDG",  value: vals.heading.toFixed(0).padStart(3, "0") + "°", color: t.text },
    { label: "ROLL", value: vals.roll.toFixed(0)  + "°", color: t.dim },
    { label: "PTCH", value: vals.pitch.toFixed(0) + "°", color: t.dim }
  ];

  for (let i = 0; i < rows.length; ++i) {
    const ly = startY + i * lineH;
    if (ly + lineH > h - 4) break;
    ctx.fillStyle = t.muted;
    ctx.font      = "9px monospace";
    ctx.textAlign = "start";
    ctx.fillText(rows[i].label, rx, ly);
    ctx.fillStyle = rows[i].color;
    ctx.font      = "bold 10px monospace";
    ctx.textAlign = "end";
    ctx.fillText(rows[i].value, rx + rw, ly);
  }
}

// -- entry point ----------------------------------------------------------

function paint(ctx, w, h) {
  const t = theme();

  ctx.fillStyle = t.bg;
  ctx.fillRect(0, 0, w, h);

  if (datasets.length < 11) {
    ctx.fillStyle    = t.dim;
    ctx.font         = (w < 320 ? "9px" : "11px") + " monospace";
    ctx.textAlign    = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("Waiting for telemetry...", w / 2, h / 2);
    return;
  }

  const vals = {
    lat:      Number(datasets[0].value)  || 0,
    lon:      Number(datasets[1].value)  || 0,
    heading:  Number(datasets[2].value)  || 0,
    alt:      Number(datasets[3].value)  || 0,
    airspeed: Number(datasets[4].value)  || 0,
    vspeed:   Number(datasets[5].value)  || 0,
    roll:     Number(datasets[6].value)  || 0,
    pitch:    Number(datasets[7].value)  || 0,
    voltage:  Number(datasets[8].value)  || 0,
    current:  Number(datasets[9].value)  || 0,
    battery:  Number(datasets[10].value) || 0
  };
  vals.state = infer_state(vals.alt, vals.vspeed, vals.airspeed, vals.battery);

  const mode    = pick_layout(w, h);
  const headerH = draw_header(ctx, w, t, vals.lat, vals.lon, vals.heading,
                              vals.state, vals.battery, mode);

  if      (mode === "full")    paint_full   (ctx, w, h, vals, t, headerH);
  else if (mode === "square")  paint_square (ctx, w, h, vals, t, headerH);
  else                          paint_compact(ctx, w, h, vals, t, headerH);
}

